/* Afintrix print style — Phase 3.
   Montserrat, brand blue headings, a gold rule under the heading, and the same
   grey table header the desk uses, so a printed document and the screen it came
   from read as one product. */
.print-format {
	font-family: "Montserrat", "Helvetica Neue", Arial, sans-serif;
	color: #1b1f27;
	font-size: 9.5pt;
}

.print-format h1,
.print-format h2,
.print-format h3,
.print-format h4 {
	font-family: "Montserrat", "Helvetica Neue", Arial, sans-serif;
	font-weight: 700;
	color: #10141c;
	letter-spacing: -0.01em;
}

.print-heading {
	padding-bottom: 10px;
	margin-bottom: 18px;
	border-bottom: 2px solid #1E39D6;
}

.print-heading h2 {
	font-size: 20pt;
	color: #1E39D6;
	margin: 0;
}

.print-heading .sub-heading {
	color: #8d96a8;
	font-size: 9pt;
}

.print-format table {
	border-collapse: collapse;
}

.print-format th {
	background-color: #f5f7fa !important;
	color: #48505f !important;
	font-weight: 600;
	border-bottom: 1px solid #e4e8ef !important;
	text-transform: none;
}

.print-format td,
.print-format th {
	padding: 7px 8px !important;
	border-color: #e4e8ef !important;
}

.print-format .table-bordered,
.print-format .table-bordered td,
.print-format .print-format-table {
	border-color: #e4e8ef !important;
}

/* the brand's gold, used the way the kit uses it: as a rule, never as text */
.print-format .letter-head {
	border-bottom: 3px solid #D5AA55;
	padding-bottom: 12px;
	margin-bottom: 18px;
}

.print-format .importance,
.print-format .grand-total,
.print-format .totals .value {
	font-weight: 700;
	color: #121CA4;
}

.print-format .data-field .value {
	color: #1b1f27;
}

.print-format .terms,
.print-format small,
.print-format .text-muted {
	color: #6b7484 !important;
}

#footer-html,
.print-format .footer {
	color: #8d96a8;
	font-size: 8pt;
	border-top: 1px solid #e4e8ef;
	padding-top: 8px;
}

/* ---- shared document layout, used by every Afintrix print format ---- */
.afx-print { font-family: "Montserrat", "Helvetica Neue", Arial, sans-serif; color: #1b1f27; }
.afx-print-head { display: flex; justify-content: space-between; align-items: flex-start;
	padding-bottom: 12px; margin-bottom: 20px; border-bottom: 2px solid #1E39D6; }
.afx-print-title { font-size: 22pt; font-weight: 700; color: #1E39D6; line-height: 1.1; }
.afx-print-number { color: #8d96a8; font-size: 10pt; }
.afx-print-meta { text-align: right; font-size: 9pt; }
.afx-print-meta span { color: #8d96a8; display: inline-block; min-width: 42px; }
.afx-print-parties { display: flex; gap: 40px; margin-bottom: 22px; }
.afx-print-parties > div { flex: 1 1 0; }
.afx-print-label { font-size: 8pt; text-transform: uppercase; letter-spacing: 0.06em;
	color: #8d96a8; margin-bottom: 4px; }
.afx-print-strong { font-weight: 600; }
.afx-print-muted { color: #6b7484; font-size: 9pt; }
.afx-print-items { width: 100%; margin-bottom: 14px; }
.afx-print-items th { background: #f5f7fa !important; color: #48505f !important; font-weight: 600; }
.afx-print-summary { display: flex; justify-content: flex-end; margin-top: 6px; }
.afx-print-summary table { min-width: 280px; }
.afx-print-summary td { padding: 5px 8px; }
.afx-print-total td { border-top: 2px solid #D5AA55; font-weight: 700; color: #121CA4; font-size: 11pt; }
.afx-print-terms { margin-top: 22px; font-size: 9pt; color: #48505f; }
.afx-print-signatures { display: flex; gap: 60px; margin-top: 44px; font-size: 9pt; color: #6b7484; }
.afx-print-signatures > div { flex: 1 1 0; }
.afx-print-signline { display: block; border-top: 1px solid #b9c1cf; margin-bottom: 6px; }
